//! End-to-end tests for HTTPS interception.
//!
//! Every test runs the real proxy, a real TLS client, and a real TLS origin
//! server, all in this process on OS-assigned ports. The shape under test is
//! the one interception is for:
//!
//! ```text
//! client --TLS #1--> proxy --HTTP/1.1--> proxy --TLS #2--> origin
//!    trusts the proxy's CA                    trusts the origin's CA
//! ```
//!
//! Both certificates are generated by the test that needs them, from CAs
//! generated for that test. Nothing here uses, reads, or writes a stored
//! development CA, and nothing reaches the network: no external service, no
//! public web site, no fixed port. Every wait is on something the other side
//! actually did, so there are no sleeps.

mod support;

use support::{
    connect_request, origin_form_request, send_raw, HttpsClient, Proxy, RawServer, TlsOrigin,
    UntrustedTlsOrigin,
};

use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::time::{timeout, Duration};

/// Long enough to absorb a loaded machine, short enough that a proxy that
/// never answers fails the test instead of hanging it.
const TEST_TIMEOUT: Duration = Duration::from_secs(5);

/// A plain `200 OK` with a body of known length.
const HELLO: &[u8] =
    b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 12\r\n\r\nhello, https";

#[tokio::test]
async fn a_request_inside_an_intercepted_session_reaches_the_origin_and_comes_back() {
    let origin = TlsOrigin::responding_with("localhost", HELLO).await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting(proxy.trust());

    let response = client
        .exchange(
            proxy.addr(),
            &origin.authority(),
            origin.host(),
            &origin_form_request("GET", "/hello", &origin.authority(), &[]),
        )
        .await;

    assert_eq!(response.status, 200);
    assert_eq!(response.body_text(), "hello, https");

    // The request the proxy decrypted, forwarded, and re-encrypted: the
    // origin saw it, so the proxy really did read it rather than pass bytes
    // through.
    let forwarded = origin.only_request();
    assert_eq!(forwarded.method, "GET");
    assert_eq!(forwarded.target, "/hello");
    assert_eq!(forwarded.version, "HTTP/1.1");

    proxy.stop().await;
}

#[tokio::test]
async fn the_client_is_served_the_proxys_certificate_and_not_the_origins() {
    let origin = TlsOrigin::responding_with("localhost", HELLO).await;
    let proxy = Proxy::trusting(origin.trust()).await;

    // A client that trusts the proxy's CA gets through; the same client
    // trusting only the origin's CA does not, which is only possible if what
    // it was offered was the proxy's certificate.
    let trusting_the_proxy = HttpsClient::trusting(proxy.trust());
    let trusting_the_origin = HttpsClient::trusting(origin.trust());

    let (connect, accepted) = trusting_the_proxy
        .connect(proxy.addr(), &origin.authority(), origin.host())
        .await;
    assert_eq!(connect.status, 200);
    accepted.expect("the proxy's own certificate is accepted");

    let (connect, refused) = trusting_the_origin
        .connect(proxy.addr(), &origin.authority(), origin.host())
        .await;
    assert_eq!(connect.status, 200);
    refused.expect_err("the origin's certificate was never presented to the client");

    proxy.stop().await;
}

#[tokio::test]
async fn the_request_body_reaches_the_origin() {
    let origin = TlsOrigin::responding_with("localhost", HELLO).await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting(proxy.trust());

    let mut request = origin_form_request(
        "POST",
        "/submit",
        &origin.authority(),
        &[("content-type", "text/plain"), ("content-length", "9")],
    );
    request.extend_from_slice(b"some body");

    let response = client
        .exchange(proxy.addr(), &origin.authority(), origin.host(), &request)
        .await;

    assert_eq!(response.status, 200);

    let forwarded = origin.only_request();
    assert_eq!(forwarded.method, "POST");
    assert_eq!(forwarded.body_text(), "some body");

    proxy.stop().await;
}

#[tokio::test]
async fn the_origins_own_headers_and_status_reach_the_client() {
    let origin = TlsOrigin::responding_with(
        "localhost",
        b"HTTP/1.1 418 I'm a teapot\r\nX-Origin: yes\r\nContent-Length: 4\r\n\r\nteap",
    )
    .await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting(proxy.trust());

    let response = client
        .exchange(
            proxy.addr(),
            &origin.authority(),
            origin.host(),
            &origin_form_request("GET", "/", &origin.authority(), &[]),
        )
        .await;

    assert_eq!(response.status, 418);
    assert_eq!(response.header("x-origin"), Some("yes"));
    assert_eq!(response.body_text(), "teap");

    proxy.stop().await;
}

#[tokio::test]
async fn the_clients_own_headers_reach_the_origin_and_the_proxys_do_not() {
    let origin = TlsOrigin::responding_with("localhost", HELLO).await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting(proxy.trust());

    client
        .exchange(
            proxy.addr(),
            &origin.authority(),
            origin.host(),
            &origin_form_request(
                "GET",
                "/",
                &origin.authority(),
                &[
                    ("authorization", "Bearer token"),
                    ("accept", "application/json"),
                    ("proxy-connection", "keep-alive"),
                ],
            ),
        )
        .await;

    let forwarded = origin.only_request();
    // The client's credentials are for the origin, and this hop is the
    // proxy's own business.
    assert_eq!(forwarded.header("authorization"), Some("Bearer token"));
    assert_eq!(forwarded.header("accept"), Some("application/json"));
    assert_eq!(forwarded.header("proxy-connection"), None);

    proxy.stop().await;
}

#[tokio::test]
async fn the_host_the_client_asked_for_reaches_the_origin() {
    let origin = TlsOrigin::responding_with("localhost", HELLO).await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting(proxy.trust());

    client
        .exchange(
            proxy.addr(),
            &origin.authority(),
            origin.host(),
            &origin_form_request("GET", "/", &origin.authority(), &[]),
        )
        .await;

    assert_eq!(
        origin.only_request().header("host"),
        Some(origin.authority().as_str())
    );

    proxy.stop().await;
}

#[tokio::test]
async fn a_session_can_be_intercepted_for_a_loopback_address() {
    // A `CONNECT` to an address rather than a name: the certificate the proxy
    // presents has to carry an IP subject alternative name, and the
    // certificate it verifies upstream has to be matched against the address.
    let origin = TlsOrigin::responding_with("127.0.0.1", HELLO).await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting(proxy.trust());

    let response = client
        .exchange(
            proxy.addr(),
            &origin.authority(),
            origin.host(),
            &origin_form_request("GET", "/", &origin.authority(), &[]),
        )
        .await;

    assert_eq!(response.status, 200);
    assert_eq!(response.body_text(), "hello, https");
    assert_eq!(origin.only_request().target, "/");

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn several_intercepted_sessions_run_at_the_same_time() {
    let origin = TlsOrigin::start("localhost", |request| {
        format!(
            "HTTP/1.1 200 OK\r\nContent-Length: {}\r\n\r\n{}",
            request.target.len(),
            request.target
        )
        .into_bytes()
    })
    .await;
    let proxy = Proxy::trusting(origin.trust()).await;

    let authority = origin.authority();
    let host = origin.host().to_owned();
    let proxy_addr = proxy.addr();
    let trust = proxy.trust();

    // Eight clients, each with its own `CONNECT`, its own TLS session, and
    // its own request. Every answer names the path that client asked for, so
    // a session that got another session's response fails the test.
    let mut exchanges = Vec::new();
    for index in 0..8 {
        let authority = authority.clone();
        let host = host.clone();
        let trust = trust.clone();
        exchanges.push(tokio::spawn(async move {
            let path = format!("/client-{index}");
            let client = HttpsClient::trusting(trust);
            let response = client
                .exchange(
                    proxy_addr,
                    &authority,
                    &host,
                    &origin_form_request("GET", &path, &authority, &[]),
                )
                .await;

            (path, response)
        }));
    }

    for exchange in exchanges {
        let (path, response) = timeout(TEST_TIMEOUT, exchange)
            .await
            .expect("every session finishes")
            .expect("client task does not panic");

        assert_eq!(response.status, 200);
        assert_eq!(response.body_text(), path);
    }

    assert_eq!(origin.requests().len(), 8);
    assert_eq!(
        proxy.certified_hosts(),
        1,
        "eight sessions to one host should share one certificate"
    );

    proxy.stop().await;
}

#[tokio::test]
async fn an_origin_whose_certificate_is_not_trusted_gets_no_request() {
    let origin = UntrustedTlsOrigin::start("localhost").await;
    // The proxy trusts only the public web PKI, which the origin's CA is not
    // in. Verification is on, so the origin's session is never established.
    let proxy = Proxy::start().await;
    let client = HttpsClient::trusting(proxy.trust());

    let (connect, session) = client
        .connect(proxy.addr(), &origin.authority(), "localhost")
        .await;

    // The client's own session is established — the proxy answers a handshake
    // before it makes one — and then the connection ends with no response,
    // because the proxy would not talk to an origin it could not verify.
    assert_eq!(connect.status, 200);
    let mut session = session.expect("the client accepts the proxy's certificate");

    let answered = timeout(TEST_TIMEOUT, async {
        session
            .write_all(&origin_form_request("GET", "/", "localhost", &[]))
            .await?;
        session.flush().await?;

        let mut answer = Vec::new();
        session.read_to_end(&mut answer).await.map(|_| answer)
    })
    .await
    .expect("the proxy closes the session");

    // Either an announced close or a dropped connection; what matters is that
    // no HTTP response was produced and nothing was downgraded to plaintext.
    let received = answered.unwrap_or_default();
    assert!(
        received.is_empty(),
        "the proxy answered for an origin it could not verify: {:?}",
        String::from_utf8_lossy(&received)
    );

    proxy.stop().await;
}

#[tokio::test]
async fn a_client_that_does_not_trust_the_ca_is_refused() {
    let origin = TlsOrigin::responding_with("localhost", HELLO).await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting_nothing_local();

    let (connect, session) = client
        .connect(proxy.addr(), &origin.authority(), origin.host())
        .await;

    // The `CONNECT` is answered — the proxy has no way to know what the
    // client trusts until the handshake — and the handshake then fails, which
    // is interception being visible rather than silent.
    assert_eq!(connect.status, 200);
    session.expect_err("a client that has not installed the CA must not be fooled");

    assert!(
        origin.requests().is_empty(),
        "a request was forwarded for a client that never completed a handshake"
    );

    proxy.stop().await;
}

#[tokio::test]
async fn a_client_that_sends_no_tls_at_all_gets_no_session() {
    let origin = TlsOrigin::responding_with("localhost", HELLO).await;
    let proxy = Proxy::trusting(origin.trust()).await;

    let mut client = tokio::net::TcpStream::connect(proxy.addr())
        .await
        .expect("connect to the proxy");
    client
        .write_all(&connect_request(&origin.authority()))
        .await
        .expect("send the CONNECT");

    // Plain HTTP where a TLS handshake belongs. There is nothing to intercept
    // and nothing is passed through, so the connection ends.
    let answer = timeout(TEST_TIMEOUT, async {
        let mut head = [0_u8; 39];
        client.read_exact(&mut head).await?;
        client
            .write_all(&origin_form_request("GET", "/", "localhost", &[]))
            .await?;
        client.flush().await?;

        let mut rest = Vec::new();
        client.read_to_end(&mut rest).await.map(|_| rest)
    })
    .await
    .expect("the proxy closes the connection");

    // What comes back, if anything, is the TLS alert that says the bytes were
    // not a handshake — never an HTTP response, and never anything the origin
    // said, because nothing was ever sent to it.
    let received = answer.unwrap_or_default();
    let text = String::from_utf8_lossy(&received).into_owned();
    assert!(
        !text.contains("HTTP/1."),
        "the proxy carried plaintext through a CONNECT: {text:?}"
    );
    assert!(
        !text.contains("hello, https"),
        "the origin's response reached a client that never spoke TLS: {text:?}"
    );
    assert!(origin.requests().is_empty());

    proxy.stop().await;
}

#[tokio::test]
async fn a_connect_to_something_that_is_not_tls_gets_no_session() {
    // Something is listening, and it is not a TLS server. The `CONNECT`
    // succeeds because the TCP connection did; the origin's handshake then
    // does not, and no plaintext is exchanged with it.
    let upstream = RawServer::echoing().await;
    let proxy = Proxy::start().await;
    let client = HttpsClient::trusting(proxy.trust());

    let (connect, session) = client
        .connect(proxy.addr(), &upstream.authority(), "127.0.0.1")
        .await;

    assert_eq!(connect.status, 200);
    let mut session = session.expect("the client accepts the proxy's certificate");

    let answered = timeout(TEST_TIMEOUT, async {
        session
            .write_all(&origin_form_request("GET", "/", "127.0.0.1", &[]))
            .await?;
        session.flush().await?;

        let mut answer = Vec::new();
        session.read_to_end(&mut answer).await.map(|_| answer)
    })
    .await
    .expect("the proxy closes the session");

    assert!(
        answered.unwrap_or_default().is_empty(),
        "the proxy produced a response from a server it never spoke TLS to"
    );

    proxy.stop().await;
}

#[tokio::test]
async fn an_origin_that_answers_with_nothing_is_a_bad_gateway_inside_the_session() {
    // A TLS origin that establishes a session and then says nothing: the
    // proxy has a verified session and no HTTP response, which is a gateway
    // failure it can report inside the client's own session.
    let origin = TlsOrigin::responding_with("localhost", b"").await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting(proxy.trust());

    let response = client
        .exchange(
            proxy.addr(),
            &origin.authority(),
            origin.host(),
            &origin_form_request("GET", "/", &origin.authority(), &[]),
        )
        .await;

    assert_eq!(response.status, 502);
    assert!(
        response.body_text().contains("destination server"),
        "unhelpful body: {:?}",
        response.body_text()
    );
    for leak in ["rustls", "hyper", "io::", "Error {", "src/"] {
        assert!(
            !response.body_text().contains(leak),
            "error body leaks internals ({leak}): {:?}",
            response.body_text()
        );
    }

    proxy.stop().await;
}

#[tokio::test]
async fn an_intercepted_session_is_closed_cleanly() {
    let origin = TlsOrigin::responding_with("localhost", HELLO).await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting(proxy.trust());

    let (connect, session) = client
        .connect(proxy.addr(), &origin.authority(), origin.host())
        .await;
    assert_eq!(connect.status, 200);
    let mut session = session.expect("the client accepts the proxy's certificate");

    let answer = timeout(TEST_TIMEOUT, async {
        session
            .write_all(&origin_form_request("GET", "/", &origin.authority(), &[]))
            .await?;
        session.flush().await?;

        let mut answer = Vec::new();
        session.read_to_end(&mut answer).await.map(|_| answer)
    })
    .await
    .expect("the session closes");

    // Reaching the end of the stream without an error is what proves the
    // close was announced: a session that simply dropped its socket surfaces
    // here as an unexpected end-of-file, which is what clients complain
    // about and is indistinguishable from a truncated response.
    let answer = answer.expect("the close was announced rather than the socket dropped");
    assert!(
        String::from_utf8_lossy(&answer).starts_with("HTTP/1.1 200 "),
        "unexpected answer: {:?}",
        String::from_utf8_lossy(&answer)
    );

    proxy.stop().await;
}

#[tokio::test]
async fn a_forwarded_plaintext_request_still_works_alongside_interception() {
    let origin = TlsOrigin::responding_with("localhost", HELLO).await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting(proxy.trust());

    client
        .exchange(
            proxy.addr(),
            &origin.authority(),
            origin.host(),
            &origin_form_request("GET", "/", &origin.authority(), &[]),
        )
        .await;

    // The plaintext route is untouched by any of this: an https:// URL in an
    // ordinary proxy request is still refused rather than sent in the clear.
    let response = send_raw(
        proxy.addr(),
        b"GET https://example.test/ HTTP/1.1\r\nHost: example.test\r\n\r\n",
    )
    .await;

    assert_eq!(response.status, 501);

    proxy.stop().await;
}
